class Fenwick:
    """Fenwick tree aka binary indexed tree"""
    def __init__(self, n):
        self.nums = [0]*(n+1)

    def sum(self, k): 
        ans = 0
        while k: 
            ans += self.nums[k]
            k &= k-1
        return ans 

    def add(self, i, x): 
        i += 1
        while i < len(self.nums): 
            self.nums[i] += x
            i += i & -i


class Solution:
    def createSortedArray(self, instructions: List[int]) -> int:
        ans = 0
        fen = Fenwick(10**5)
        freq = {} # frequency of each instructions
        for i, x in enumerate(instructions): 
            less = fen.sum(x)
            more = i - freq.get(x, 0) - less
            ans += min(less, more)
            fen.add(x, 1)
            freq[x] = 1 + freq.get(x, 0)
        return ans % 1_000_000_007

class Solution:
	def minimumDeletions(self, s: str) -> int:
		preSum = [0] * (len(s) + 1)
		sufSum = [0] * (len(s) + 1)

		for i in range(len(s)):
			if s[i] == "a":
				preSum[i] += 1 + preSum[i-1]

			else:
				preSum[i] = preSum[i-1]

			if s[len(s)-i-1] == "b":
				sufSum[len(s)-i-1] += 1 + sufSum[len(s)-i]

			else:
				sufSum[len(s)-i-1] += sufSum[len(s)-i]

		maxStringLength = 0
		for i in range(len(s)):
			if preSum[i] + sufSum[i] > maxStringLength:
				maxStringLength = preSum[i] + sufSum[i]

		return len(s) - maxStringLength

class Solution:
    def minimumDeletions(self, s: str) -> int:
        result = b_cnt = 0
        for c in s:
            if c == 'b':
                b_cnt += 1
            elif b_cnt:
                b_cnt -= 1
                result += 1
        return result

